insert into public.topics (id, name, level, position, description) values
  ('fundamentals', 'Programming Fundamentals', 'Beginner', 1, 'Variables, types, loops, methods and Big-O: the toolkit every algorithm is built from.'),
  ('arrays', 'Arrays', 'Beginner', 2, 'Indexing, insertion and deletion, two pointers and prefix sums.'),
  ('strings', 'Strings', 'Beginner', 3, 'Immutability, StringBuilder, palindromes and character counting.'),
  ('searching', 'Searching Algorithms', 'Beginner', 4, 'Linear search, binary search and the lower-bound pattern.'),
  ('sorting', 'Sorting Algorithms', 'Beginner', 5, 'Bubble, selection, insertion and merge sort, plus stability.'),
  ('recursion', 'Recursion', 'Beginner', 6, 'Base cases, the call stack and backtracking.'),
  ('linked-lists', 'Linked Lists', 'Intermediate', 7, 'Nodes and pointers, reversal and fast/slow pointers.'),
  ('stacks', 'Stacks', 'Intermediate', 8, 'Last in, first out: push, pop and bracket matching.'),
  ('queues', 'Queues', 'Intermediate', 9, 'First in, first out: circular queues and deques.'),
  ('hashing', 'Hashing', 'Intermediate', 10, 'Hash functions, collisions, HashMap and HashSet.'),
  ('trees', 'Trees', 'Intermediate', 11, 'Binary trees, traversals and recursive tree thinking.'),
  ('bst', 'Binary Search Trees', 'Intermediate', 12, 'Ordered trees: search, insert, delete and validation.'),
  ('heaps', 'Heaps', 'Advanced', 13, 'Priority queues, sift up/down and top-k problems.'),
  ('graphs', 'Graphs', 'Advanced', 14, 'Representations, BFS, DFS and shortest paths.'),
  ('greedy', 'Greedy Algorithms', 'Advanced', 15, 'Locally best choices, and when they are globally best.'),
  ('dynamic-programming', 'Dynamic Programming', 'Advanced', 16, 'Overlapping subproblems, memoization and tabulation.')
